// WF-13: classify an execution error and decide if a safe retry is allowed.
const e = $input.first().json;
const message = String(e.error?.message || e.message || 'Unknown error');
const workflow = String(e.workflow?.name || e.execution?.workflowData?.name || 'unknown');

const transient = /(timeout|ECONN|ETIMEDOUT|429|rate limit|temporar)/i.test(message);
const credential = /(401|403|credential|token|auth|permission)/i.test(message);

let classification = 'UNKNOWN';
if (transient) classification = 'TRANSIENT';
else if (credential) classification = 'CREDENTIAL';
else if (/INVALID_LEAD|validation|required/i.test(message)) classification = 'DATA';
else classification = 'PERMANENT';

return [{ json: {
  workflow_name: workflow,
  execution_id: e.execution?.id || null,
  error_code: e.error?.name || null,
  message,
  classification,
  retry_safe: classification === 'TRANSIENT',
  retry_count: 0,
  occurred_at: new Date().toISOString(),
} }];

// WF-13: notify admin when the error is NOT safely self-retryable.
// Scaffold: no send. Wire SMTP (n8n credential) or WhatsApp-to-owner here.
const j = $('Classify Error').first().json;
const shouldNotify = j.classification !== 'TRANSIENT';
return [{ json: {
  ...j,
  notified: false,
  action: shouldNotify ? 'NOTIFY_ADMIN' : 'RETRY_SCHEDULED',
  note: 'Never create infinite retry loops; cap retries and escalate when unresolved.',
} }];
